-- Clean bootstrap 002: strict sector helpers and baseline RLS.
CREATE OR REPLACE FUNCTION public.owns_customer(customer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.customers c WHERE c.id=customer AND c.user_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.can_read_customer(customer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin() OR public.has_role('comptable') OR EXISTS(SELECT 1 FROM public.customers c WHERE c.id=customer AND ((public.has_role('commercial_staff') AND c.commercial_id=auth.uid()) OR (public.has_role('client_b2b') AND c.user_id=auth.uid()))) $$;
CREATE OR REPLACE FUNCTION public.can_read_order(ord uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin() OR public.has_role('comptable','warehouse_staff') OR EXISTS(SELECT 1 FROM public.sales_orders so JOIN public.customers c ON c.id=so.customer_id WHERE so.id=ord AND ((public.has_role('commercial_staff') AND (so.sales_rep_id=auth.uid() OR c.commercial_id=auth.uid())) OR (public.has_role('client_b2b') AND c.user_id=auth.uid()))) OR EXISTS(SELECT 1 FROM public.deliveries d WHERE d.order_id=ord AND public.has_role('delivery_agent') AND d.delivery_agent_id=auth.uid()) $$;

DO $$ DECLARE p record; BEGIN FOR p IN SELECT schemaname,tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN('roles','user_profiles','product_categories','products','warehouse_locations','customers','sales_orders','order_items','inventory_stock','stock_movements','invoices','payments','expenses','delivery_routes','deliveries') LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON %I.%I',p.policyname,p.schemaname,p.tablename); END LOOP; END $$;
DROP POLICY IF EXISTS roles_read ON public.roles;
CREATE POLICY roles_read ON public.roles FOR SELECT TO authenticated USING(is_system OR public.is_admin());
DROP POLICY IF EXISTS roles_admin_manage ON public.roles;
CREATE POLICY roles_admin_manage ON public.roles FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
DROP POLICY IF EXISTS profiles_read ON public.user_profiles;
CREATE POLICY profiles_read ON public.user_profiles FOR SELECT TO authenticated USING(public.is_admin() OR id=auth.uid());
DROP POLICY IF EXISTS profiles_self_update ON public.user_profiles;
CREATE POLICY profiles_self_update ON public.user_profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
DROP POLICY IF EXISTS profiles_admin_update ON public.user_profiles;
CREATE POLICY profiles_admin_update ON public.user_profiles FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
DROP POLICY IF EXISTS categories_read ON public.product_categories;
CREATE POLICY categories_read ON public.product_categories FOR SELECT TO authenticated USING(true);
DROP POLICY IF EXISTS categories_admin ON public.product_categories;
CREATE POLICY categories_admin ON public.product_categories FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
DROP POLICY IF EXISTS products_read ON public.products;
CREATE POLICY products_read ON public.products FOR SELECT TO authenticated USING(is_active OR public.has_role('admin','warehouse_staff','comptable','acheteur'));
DROP POLICY IF EXISTS products_admin ON public.products;
CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
DROP POLICY IF EXISTS warehouses_read ON public.warehouse_locations;
CREATE POLICY warehouses_read ON public.warehouse_locations FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('warehouse_staff','delivery_agent') AND (public.has_role('delivery_agent') OR id=(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid())));
DROP POLICY IF EXISTS warehouses_admin ON public.warehouse_locations;
CREATE POLICY warehouses_admin ON public.warehouse_locations FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
DROP POLICY IF EXISTS customers_read ON public.customers;
CREATE POLICY customers_read ON public.customers FOR SELECT TO authenticated USING(public.can_read_customer(id));
DROP POLICY IF EXISTS customers_sales_insert ON public.customers;
CREATE POLICY customers_sales_insert ON public.customers FOR INSERT TO authenticated WITH CHECK(public.is_admin() OR (public.has_role('commercial_staff') AND commercial_id=auth.uid()));
DROP POLICY IF EXISTS customers_sales_update ON public.customers;
CREATE POLICY customers_sales_update ON public.customers FOR UPDATE TO authenticated USING(public.is_admin() OR (public.has_role('commercial_staff') AND commercial_id=auth.uid())) WITH CHECK(public.is_admin() OR (public.has_role('commercial_staff') AND commercial_id=auth.uid()));
DROP POLICY IF EXISTS orders_read ON public.sales_orders;
CREATE POLICY orders_read ON public.sales_orders FOR SELECT TO authenticated USING(public.can_read_order(id));
DROP POLICY IF EXISTS order_items_read ON public.order_items;
CREATE POLICY order_items_read ON public.order_items FOR SELECT TO authenticated USING(public.can_read_order(order_id));
DROP POLICY IF EXISTS inventory_read ON public.inventory_stock;
CREATE POLICY inventory_read ON public.inventory_stock FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('comptable') OR (public.has_role('warehouse_staff') AND warehouse_id=(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid())));
DROP POLICY IF EXISTS movements_read ON public.stock_movements;
CREATE POLICY movements_read ON public.stock_movements FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('comptable') OR (public.has_role('warehouse_staff') AND warehouse_id=(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid())));
DROP POLICY IF EXISTS invoices_read ON public.invoices;
CREATE POLICY invoices_read ON public.invoices FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('comptable') OR public.can_read_customer(customer_id));
DROP POLICY IF EXISTS payments_read ON public.payments;
CREATE POLICY payments_read ON public.payments FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('comptable') OR EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=invoice_id AND public.can_read_customer(i.customer_id)));
DROP POLICY IF EXISTS expenses_accounting ON public.expenses;
CREATE POLICY expenses_accounting ON public.expenses FOR SELECT TO authenticated USING(public.is_admin() OR public.has_role('comptable') OR created_by=auth.uid());
DROP POLICY IF EXISTS routes_read ON public.delivery_routes;
CREATE POLICY routes_read ON public.delivery_routes FOR SELECT TO authenticated USING(public.is_admin() OR (public.has_role('delivery_agent') AND delivery_agent_id=auth.uid()) OR (public.has_role('warehouse_staff') AND warehouse_id=(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid())));
DROP POLICY IF EXISTS deliveries_read ON public.deliveries;
CREATE POLICY deliveries_read ON public.deliveries FOR SELECT TO authenticated USING(public.is_admin() OR (public.has_role('delivery_agent') AND delivery_agent_id=auth.uid()) OR (public.has_role('warehouse_staff') AND warehouse_id=(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid())) OR public.can_read_order(order_id));
